import type {ContextHistoryRecord,ContextProvenance,ContextScenario,ContextFeatures,ContextPrediction,DemoSource,DemoHistoryRecord} from './inventoryContextAI';
export type DemoTimestamp={seconds:number;nanoseconds:number};
export type ReviewInput={operationId:string;requirementId:string;expectedVersion:number;decision:'Accept'|'Reject';notes:string};
export type ReviewOutcome={state:'Completed'|'Cancelled';operationId:string;requirementId:string;eventId:string|null;decision:'Accept'|'Reject'|null;replayed:boolean};
export type RiskBasis={experimentId:string;experimentActor:string;operationId:string;sourceProduct:DemoSource;scenario:ContextScenario;features:ContextFeatures;inputSha256:string;prediction:ContextPrediction;source:ContextHistoryRecord['source'];requestedAtMs:number};
type Common=ContextProvenance&{ownerId:string;basis:RiskBasis;policyVersion:'demo-risk-review-1.0';createdAt:DemoTimestamp;version:number};
export type DemoRiskAlert=Common&{requirementId:string;version:1};
export type DemoReviewSummary={operationId:string;eventId:string;decision:'Accept'|'Reject';notes:string;reviewedBy:string;reviewedAt:DemoTimestamp};
export type DemoReorderRequirement=Common&({alertId:string;status:'Pending';version:1;review:null}|{alertId:string;status:'Accepted'|'Rejected';version:2;review:DemoReviewSummary});
export type DemoReorderEvent=ContextProvenance&{ownerId:string;requirementId:string;experimentId:string;operationId:string;actor:string;decision:'Accept'|'Reject';notes:string;fromVersion:1;toVersion:2;at:DemoTimestamp;version:1};
export type Decoded<T,K>={kind:K;id:string;record:T}|{kind:'unsupported';id:string;reason:string};
export const DEMO_REORDER_POLICY:'demo-risk-review-1.0';
export function isDemoRiskLabel(label:unknown):boolean;
export function validateDemoReorderReviewInput(value:unknown):ReviewInput;
export function validateDemoReorderOutcome(value:unknown,input:ReviewInput):ReviewOutcome;
export function decodeDemoRiskAlert(value:unknown,id:string):Promise<Decoded<DemoRiskAlert,'alert'>>;
export function decodeDemoReorderRequirement(value:unknown,id:string):Promise<Decoded<DemoReorderRequirement,'requirement'>>;
export function decodeDemoReorderEvent(value:unknown,id:string):Decoded<DemoReorderEvent,'event'>;
export function verifyDemoReorderReviewEvent(value:{id:string;requirement:DemoReorderRequirement;eventId:string;event:unknown}):DemoReorderEvent;
export function verifyDemoReorderLineage(value:{id:string;alert:unknown;requirement:unknown;experiment:unknown}):Promise<{id:string;alert:DemoRiskAlert;requirement:DemoReorderRequirement;experiment:DemoHistoryRecord}>;
